<div class="page-head"><div><p class="eyebrow">Inventory</p><h1>Stock History</h1><p>Track every stock in, stock out and adjustment record.</p></div></div><section class="panel"><div class="table-wrap"><table class="table"><tr><th>Type</th><th>Product</th><th>SKU</th><th>Quantity</th><th>Note</th><th>By</th><th>Date</th></tr><?php foreach($history as $r): ?><tr><td><span class="badge <?=$r['type']==='IN'?'green':($r['type']==='OUT'?'red':'gray')?>"><?=e($r['type'])?></span></td><td><b><?=e($r['product'])?></b></td><td><?=e($r['sku'])?></td><td><?=e($r['quantity'])?></td><td><?=e($r['note']??'—')?></td><td><?=e($r['user_name']??'System')?></td><td><?=e(date('d M Y, h:i A',strtotime($r['created_at'])))?></td></tr><?php endforeach; ?><?php if(!$history): ?><tr><td colspan="7" class="empty">No stock transactions yet.</td></tr><?php endif; ?></table></div></section><?php require __DIR__.'/../../../includes/role_footer.php'; ?>
